INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenschutz > Grundsätze (Art. 5) > Zweckbindung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Fordert der Grundsatz der Zweckbindung nach Art. 5 DSGVO, dass personenbezogene Daten nur für festgelegte Zwecke verarbeitet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 5 Abs. 1b verlangt festgelegte, eindeutige Zwecke"}, {"text": "Nein", "correct": false, "because": "Zweckbindung ist zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Verarbeitung personenbezogener Daten ohne klar definierten Zweck rechtmäßig sein?', 2, '[{"text": "Nein", "correct": true, "because": "Ohne Zweck fehlt die Rechtmäßigkeit nach DSGVO"}, {"text": "Ja", "correct": false, "because": "Zweck ist Voraussetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss der Zweck der Datenverarbeitung den Betroffenen immer vorab mitgeteilt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Transparenz erfordert Information über den Zweck"}, {"text": "Nein", "correct": false, "because": "Mitgeteilt werden ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Können personenbezogene Daten nach der Zweckbindung für einen neuen, nicht ursprünglich angegebenen Zweck weiterverarbeitet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Neue Zwecke erfordern eine neue Rechtsgrundlage"}, {"text": "Ja", "correct": false, "because": "Zweckänderung meist unrechtmäßig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Zweckbindung nach Art. 5 DSGVO auch dann einzuhalten, wenn die Einwilligung vorliegt?', 2, '[{"text": "Ja", "correct": true, "because": "Einwilligung muss zweckgebunden sein"}, {"text": "Nein", "correct": false, "because": "Zweckbindung gilt immer"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was bedeutet der Grundsatz der Zweckbindung nach Art. 5 DSGVO?', 2, '[{"text": "Daten nur für festgelegte Zwecke verarbeiten", "correct": true, "because": "Art. 5 Abs. 1b definiert dies"}, {"text": "Daten unbegrenzt speichern", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Daten ohne Zweck erheben", "correct": false, "because": "Verboten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Voraussetzung muss laut Art. 5 DSGVO für die Zweckbindung erfüllt sein?', 3, '[{"text": "Zweck muss vorab festgelegt sein", "correct": true, "because": "Eindeutige Zwecke sind Pflicht"}, {"text": "Zweck kann nachträglich definiert werden", "correct": false, "because": "Nicht zulässig"}, {"text": "Zweck ist optional", "correct": false, "because": "Pflichtvorgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme stellt die Zweckbindung bei der Datenverarbeitung sicher?', 2, '[{"text": "Zweck in der Datenschutzerklärung angeben", "correct": true, "because": "Transparenz und Dokumentation"}, {"text": "Daten unbegrenzt speichern", "correct": false, "because": "Widerspricht Zweckbindung"}, {"text": "Daten ohne Dokumentation erheben", "correct": false, "because": "Verstoß gegen DSGVO"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz droht bei Verstoß gegen die Zweckbindung?', 2, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen Art. 5 kann sanktioniert werden"}, {"text": "Systemstilllegung", "correct": false, "because": "Keine Standardstrafe"}, {"text": "Warnungen", "correct": false, "because": "Möglich, aber nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt der Zweckbindung ist für die Softwareplanung am relevantesten?', 2, '[{"text": "Festlegung des Verarbeitungszwecks", "correct": true, "because": "Bestimmt Datenfluss und Schutz"}, {"text": "Maximale Datenmenge", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Hohe Verarbeitungsgeschwindigkeit", "correct": false, "because": "Irrelevant"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen stellt die Zweckbindung nach Art. 5 DSGVO?', 4, '[{"text": "Festgelegte Zwecke", "correct": true, "because": "Vorab klar definiert"}, {"text": "Eindeutige Zwecke", "correct": true, "because": "Müssen präzise sein"}, {"text": "Kompatibilität mit ursprünglichem Zweck", "correct": true, "because": "Weiterverarbeitung eingeschränkt"}, {"text": "Unbegrenzte Nutzung", "correct": false, "because": "Widerspricht Zweckbindung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen unterstützen die Einhaltung der Zweckbindung?', 3, '[{"text": "Zweck in Datenschutzerklärung angeben", "correct": true, "because": "Sorgt für Transparenz"}, {"text": "Daten nur für angegebenen Zweck nutzen", "correct": true, "because": "Pflicht nach Art. 5"}, {"text": "Regelmäßige Überprüfung", "correct": true, "because": "Stellt Zweckkonformität sicher"}, {"text": "Daten ohne Zweck speichern", "correct": false, "because": "Verboten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann ein Verstoß gegen die Zweckbindung haben?', 4, '[{"text": "Bußgelder", "correct": true, "because": "Sanktionen bis 20 Mio. Euro"}, {"text": "Schadensersatz", "correct": true, "because": "Betroffene können klagen"}, {"text": "Verarbeitungsverbot", "correct": true, "because": "Aufsichtsbehörden können einschreiten"}, {"text": "Verbesserte Performance", "correct": false, "because": "Keine Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte der Zweckbindung sind bei der Datenverarbeitung zu beachten?', 3, '[{"text": "Zweck vor Verarbeitung festlegen", "correct": true, "because": "Pflicht nach Art. 5"}, {"text": "Betroffene informieren", "correct": true, "because": "Transparenz erforderlich"}, {"text": "Zweckänderung prüfen", "correct": true, "because": "Neue Rechtsgrundlage nötig"}, {"text": "Unbeschränkte Nutzung", "correct": false, "because": "Verboten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechtsgrundlagen können die Zweckbindung rechtfertigen?', 3, '[{"text": "Einwilligung", "correct": true, "because": "Zweckgebundene Zustimmung"}, {"text": "Vertragserfüllung", "correct": true, "because": "Zweck im Vertrag definiert"}, {"text": "Berechtigtes Interesse", "correct": true, "because": "Zweckabwägung erforderlich"}, {"text": "Maximale Datenmenge", "correct": false, "because": "Kein Rechtsgrund"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Zweckbindung verlangt festgelegte Zwecke für die Datenverarbeitung. b) Daten können ohne Zweck verarbeitet werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Festlegung ja, ohne Zweck nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Betroffene müssen über den Verarbeitungszweck informiert werden. b) Zweckänderung ist immer erlaubt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Information ja, Änderung eingeschränkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Verstoß gegen die Zweckbindung kann Bußgelder nach sich ziehen. b) Einwilligung hebt die Zweckbindung auf.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bußgelder ja, Einwilligung zweckgebunden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Zweckbindung schützt die Rechte der Betroffenen. b) Datenverarbeitung ohne Zweck ist rechtmäßig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schutz ja, ohne Zweck unrechtmäßig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Dokumentation des Zwecks ist Teil der Zweckbindung. b) Zweckbindung gilt nur bei Einwilligung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dokumentation ja, gilt immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

